// POST /api/sessions/:id/qa with { question }. The answer is generated by the QA service attached to the
// session service in createSessions; the gateway signature is frozen, so the route reads it from `ctx.service.qa`.
// Contract: match(parts) decides, handle(ctx) responds. See docs/ARCHITECTURE.md.
import { readJsonBody, sendJson } from '../../http-util.mjs'
import { methodNotAllowed } from './respond.mjs'

export function match(parts) {
  return parts[0] === 'api' && parts[1] === 'sessions' && parts[3] === 'qa' && parts.length === 4
}

export async function handle({ req, res, sessionId, service, requestId }) {
  if (req.method !== 'POST') return methodNotAllowed(res, ['POST'], requestId)
  const qa = service?.qa
  if (!qa) return sendJson(res, 404, { error: 'qa_disabled', message: 'Questions about stored sessions are not enabled.', requestId })
  const input = await readJsonBody(req, 8000)
  const answer = await qa.ask(sessionId, input)
  return sendJson(res, 200, { answer, requestId })
}
